mapper.select:
select id, event_id, operation_id, code, severity, title, message, suggestion, work_line, scanner_id, scanner_seq, scanner_name, scanner_ip, plc_id, plc_name, plc_ip, device_id, device_name, qr_code, address, error_code, technical_detail, created_date from operation_event
work_line = #{workLine}
order by id desc limit #{limit}

mapper.delete:
delete from operation_event
where created_date < #{cutoff}
order by id
limit #{batchSize}
